      SUBROUTINE PLTREFCC     PLOTS REFERENCE TRAJECTORYCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DEBUG.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM38B.CIN'      INCLUDE 'ELM38C.CIN'      INCLUDE 'ELM38E.CIN'      INCLUDE 'ELM38F.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OC.CIN' CC     LOCAL VARIABLESC      REAL            LB      REAL            OMAG(3,3), XMAG(3)      REAL            O1(3,3)      EQUIVALENCE     (X1,XMAG(1)), (X2,XMAG(2)), (X3,XMAG(3))      DATA            DSTEP /2.0/, NDB /6/C-------------------------------------------------------------------C      NA = KPLOT(1)      ND = KPLOT(2)C      QORIG(1) = QPLOT(1)      QORIG(2) = QPLOT(2)      IF (TYPED .EQ. 4 .OR. TYPED .EQ. 28 .OR. TYPED .EQ. 29) THEN        NANGS = INT((ABS(AL)*RADIAN + 1.0)/DSTEP)        NANGS = MAX0(NANGS,2)        DANG = AL/FLOAT(NANGS)        DLB = L/FLOAT(NANGS)        ANG = AL        LB = L        DO 20 JN = 1, NANGS        IF (H0 .EQ. 0.0) THEN          X1 = 0.0          X2 = 0.0          X3 = - LB          LB = LB - DLB        ELSE          SNA = SIN(ANG)          CSA = COS(ANG)          IF (CSA .GT. 0.5) X1 = - SNA**2/(H0*(1.0 + CSA))          IF (CSA .LE. 0.5) X1 = - (1.0 - CSA)/H0          X2 = 0.0          X3 = - SNA/H0          ANG = ANG - DANG        ENDIFC        DO 10 J = 1, 3        S = 0.0        DO 5 K = 1, 3        S = S + O(4,K,J)*XMAG(K)    5   CONTINUE        XPT(J) = X0(4,J) + S   10   CONTINUEC        QPLOT(1) = XPT(NA)/UFLOOR(1)        QPLOT(2) = XPT(ND)/UFLOOR(1)        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2) 7009   FORMAT (' QPLOT = ',2F12.5)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2) 7008   FORMAT (8F10.5)   20   CONTINUEC        QPLOT(1) = QORIG(1)        QPLOT(2) = QORIG(2)      ELSE        QPLOT(1) = X0(4,NA)/UFLOOR(1)        QPLOT(2) = X0(4,ND)/UFLOOR(1)      ENDIF      IF (DEBUG) WRITE (NDB,7004) 7004 FORMAT (' EXIT POINT OF REFERENCE TRAJECTORY')      IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)      WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)C      WIDE = 0.0      HIGH = 0.0      IF (TYPED .EQ. 1 .OR. TYPED .EQ. 20) GO TO 500      IF (NUMTYP .EQ. 0) GO TO 500      II = ISTOR(NUMTYP)      CALL SKETCH(NUMTYP)      IWIDE = IPTOJ(1)      IHIGH = IPTOJ(2)      IF (IWIDE .NE. 0) WIDE = DATA(II + IWIDE)*UFLOOR(1)      IF (IHIGH .NE. 0) HIGH = DATA(II + IHIGH)*UFLOOR(1)      IF (KPLOT(2) .EQ. 1) DIM = WIDE      IF (KPLOT(2) .EQ. 2) DIM = HIGH      IF (DIM .EQ. 0.0) GO TO 500C      IF (TYPED .EQ. 28) THEN        HAL = 0.5*AL        SN2 = SIN(HAL)        CS2 = COS(HAL)        DO 120 J = 1, 3        DO 120 K = 1, 3        OMAG(J,K) = 0.0  120   CONTINUE        OMAG(1,1) = CS2        OMAG(1,3) = - SN2        OMAG(2,2) = 1.0        OMAG(3,1) = SN2        OMAG(3,3) = CS2C        DO 130 J = 1, 3        DO 130 K = 1, 3        S1 = 0.0        DO 125 LL = 1, 3        S1 = S1 + OMAG(J,LL)*O(4,LL,K)  125   CONTINUE        O1(J,K)  =  S1  130   CONTINUEC        DO 140 J = 1, 3        DO 140 K = 1, 3        OPT(J,K) = O1(J,K)  140   CONTINUEC        SAGIT = 0.5*SN2**2/(H0*(1.0 + CS2))      ELSE        DO 150 J = 1, 3        DO 150 K = 1, 3        OPT(J,K) = O(4,J,K)  150   CONTINUE      ENDIFC      QORIG(1) = QPLOT(1)      QORIG(2) = QPLOT(2)C  500 RETURN      END